/**
 * 漆色 → 板块。全站唯一的索引。
 *
 * 面板上的漆只有四种，没有第五种（见 global.css 头注释）。所以四条板块不是
 * 各自新增一种颜色，而是**重新分配已有的四块漆**。这张表就是那次分配，
 * 也是「哪个板块是哪个颜色」这件事在全站唯一的写法。
 *
 * 改这里一处，三处同时换色：
 *   1. 板块按钮    App.vue      —— 图标与板号取自己那块漆
 *   2. 帖子板签    PostList.vue —— 每条帖子最左边那块方块
 *   3. 区块头      PostList.vue —— 标题色
 *
 * 为什么热门拿金：金是全站唯一的「当前」色（板块按钮选中＝金块）。热门是首页
 * 默认板块，让「你正在看的」和「最热的」是同一块漆——这不是撞色，是同一件事。
 */
export const 板块漆: Record<string, string> = {
  热门: 'var(--p-gold)',
  求助专区: 'var(--p-peach)',
  蜜事交流: 'var(--p-lilac)',
  匿名树洞: 'var(--p-peri)',
};

/** 板块编号。《触角》上的东西都有编号，板块也不例外。 */
export const 板块序号: Record<string, string> = {
  热门: '01',
  求助专区: '02',
  蜜事交流: '03',
  匿名树洞: '04',
};

/**
 * 板签里的 ASCII 代号。
 *
 * 板号（01–04）已经能区分四块，代号是给**色觉障碍**读者的第二重保险——
 * 四块漆里金与桃、紫与蓝在灰度上很接近，光靠色相不一定分得开。
 * 代号是拉丁字母，必须 ASCII（CJK 会被某些字体渲染成豆腐块）。
 */
export const 板块代号: Record<string, string> = {
  热门: 'HOT',
  求助专区: 'ASK',
  蜜事交流: 'TALK',
  匿名树洞: 'MASK',
};

/** 取漆色。取不到就退回面板本体的漆——不引入新颜色。 */
export function 取漆(板块: string): string {
  return 板块漆[板块] ?? 'var(--p-lilac)';
}

/** 取板号。取不到就 00，与 App.vue 的既有行为一致。 */
export function 取板号(板块: string): string {
  return 板块序号[板块] ?? '00';
}

/** 取代号。取不到就空——宁可少一行，不编一个错的。 */
export function 取代号(板块: string): string {
  return 板块代号[板块] ?? '';
}

/**
 * 板块的深度层。
 *
 * 整页是一次下潜的剖面：四条板块不是四个按钮，而是**深度轴上的四段水**。
 * 越往下越暗、越冷、越紧——同一块漆按深度降明度，一个色值都不新增。
 *
 *   z0 —— 热门。0m 浅层，满亮。最暖、最松、帖子铺得最开，是出发的地方。
 *   z1 —— 求助专区。12m 温跃层。有一点光，但偏冷；层里横着公告那条青色带。
 *   z2 —— 蜜事交流。35m 中层带。光开始不够，帖子变密、字号降一档。
 *   z3 —— 匿名树洞。60m 深暗层。最静、最密、行距最紧，一列不想被注意到的独白。
 *
 * 「换板块」在界面上就是**往下潜**：整幅的光过渡到新深度，轴上的位置标记跟着走。
 * 所以下面这张表同时是「哪一板」和「有多深」——它不是配色表，是深度表。
 */
export type 深度层 = 'z0' | 'z1' | 'z2' | 'z3';

export const 板块深度: Record<string, 深度层> = {
  热门: 'z0',
  求助专区: 'z1',
  蜜事交流: 'z2',
  匿名树洞: 'z3',
};

export function 取深度(板块: string): 深度层 {
  return 板块深度[板块] ?? 'z0';
}

/** 深度轴上的读数，米。与 板块深度 一一对应，改一处要两处一起看。 */
export const 板块深度米: Record<string, number> = {
  热门: 0,
  求助专区: 12,
  蜜事交流: 35,
  匿名树洞: 60,
};

export function 取深度米(板块: string): number {
  return 板块深度米[板块] ?? 0;
}

/** 深度读数写成轴上的样子：`0m` `12m` `35m` `60m` */
export function 取深度标(板块: string): string {
  return `${取深度米(板块)}m`;
}

/**
 * 板块的光 —— 同一块漆按深度压暗。
 *
 * 世界纪律是「全站只有四种颜色，没有第五种」。所以四条板块各占一块已有的漆，
 * 再按深度乘一个亮度系数：
 *
 *   z0 系数 1     —— 满亮，什么都不动
 *   z1 系数 0.84  —— 降一档，还看得出来是同一块漆
 *   z2 系数 0.68  —— 再降一档
 *   z3 系数 0.52  —— 最暗，但仍在可读范围内（正文另有一块不随深度变暗的读数面）
 *
 * 这样「我在哪一板」由整幅的光说，不靠任何标记。
 */
export const 深度亮度: Record<深度层, number> = {
  z0: 1,
  z1: 0.84,
  z2: 0.68,
  z3: 0.52,
};

export function 取深度亮度(板块: string): number {
  return 深度亮度[取深度(板块)];
}
