/**
 * 临时状态：搜索输入框正在打的字 + 是否在等 AI 回。
 *
 * ⚠ 兼容垫片：App.vue（下潜剖面版）引用了这个模块，但它之前在数据层没落地。
 *   这一版先给出最小导出，让界面能加载渲染；「搜索」这个功能本身的实现待另行补齐，
 *   这里只负责 UI 正在打字的那点状态，不假装搜索能用。
 */
import { ref } from 'vue';

/** 搜索框里正在打的词。只有 UI 用，写完按回车才写进变量交给 AI。 */
export const 搜索词 = ref('');

/** 已提交、在等 AI 回结果的标志。AI 写完变量后由 App 的 watch 清掉。 */
export const 搜索等待中 = ref(false);

/** 清掉上一次搜索的输入与等待态。每次重进搜索页都重置，免得看到半截旧结果。 */
export function 清空搜索(): void {
  搜索词.value = '';
  搜索等待中.value = false;
}
