/** 板块名 → 图标名 */
export function 板块图标(板块: string): string {
  switch (板块) {
    case '热门':
      return 图标.热门板块;
    case '求助专区':
      return 图标.求助专区;
    case '蜜事交流':
      return 图标.蜜事交流;
    case '匿名树洞':
      return 图标.匿名树洞;
    default:
      return 图标.最新帖子;
  }
}

/**
 * 通知连击图标的哈希池。
 *
 * 「连击」= 同一个人、同一件事，一轮里又发生了。现实里的手机通知会叠成一摞
 * 带个 ×N，这里也一样：连击的通知不重复占行，在原行上盖一个计数。
 *
 * 为什么用图标而不是 `×3` 这样的文字：本方向的字体梯队里没有等宽字，
 * 而 `×3` 跟旁边的行数、热度数长得一样，扫一眼分不清哪个是计数、哪个是正文。
 * 一个形状 + 一个数字就分得开——形状是「什么类别」，数字是「几次」。
 *
 * 用哈希而不是查表：类别只有三类，但连击行上真正有信息的是**人**，
 * 不同的人给不同的形状，整列扫下来才不平。
 */
const 连击形状 = ['fa-bolt', 'fa-bolt-lightning', 'fa-tower-broadcast'] as const;

export function 连击图标(种子: string): string {
  return 连击形状[散列(种子) % 连击形状.length];
}

/** 昵称与类别拼出来的稳定散列。头像配色与连击形状共用一套 */
function 散列(值: string): number {
  let h = 5381;
  for (let i = 0; i < 值.length; i++) h = ((h << 5) + h + 值.charCodeAt(i)) >>> 0;
  return h;
}

/**
 * 头像上的双字符缩写。
 *
 * 这是全站唯一用等宽字的地方，而它确实需要等宽：头像是一个固定尺寸的方块，
 * 「-1」和「-4」差一个字宽，不等宽的话两种头像肉眼看着不一样大。
 *
 * 按拼音首字母走，但声母 zh/ch/sh 要合回一个字母——不然「周/陈/沈」会跟
 * 「张/曹/史」撞车，八个色板里再撞一次就完全是同一个人了。
 *
 * 首字 → 拼音。只收网友昵称里真会出现的字。
 *
 * 为什么不用现成的拼音库：这个界面要打包成单文件、走 CDN 塞进消息楼层，
 * 为两个字母引一张表不划算。收不到的字走数字兜底，不会崩。
 */
