  天: 't', 寒: 'h', 小: 'x', 少: 's', 尘: 'c', 尾: 'w', 屿: 'y', 岛: 'd', 岩: 'y', 岭: 'l', 岸: 'a', 巡: 'x',
  巢: 'c', 左: 'z', 底: 'd', 归: 'g', 影: 'y', 战: 'z', 户: 'h', 打: 'd', 新: 'x', 旁: 'p', 无: 'w', 旧: 'j',
