  烬: 'j', 焰: 'y', 燎: 'l', 猎: 'l', 猛: 'm', 玫: 'm', 瑰: 'g', 用: 'y', 甲: 'j', 电: 'd', 症: 'z', 瘾: 'y',
  白: 'b', 真: 'z', 短: 'd', 石: 's', 研: 'y', 砾: 'l', 碑: 'b', 礁: 'j', 神: 's', 穴: 'x', 究: 'j', 站: 'z',
