/** 声母表。zh/ch/sh 合回一个字母，否则「周/陈/沈」会跟「张/曹/史」撞车 */
const 声母表: Record<string, string> = {
  b: 'b', p: 'p', m: 'm', f: 'f', d: 'd', t: 't', n: 'n', l: 'l',
  g: 'g', k: 'k', h: 'h', j: 'j', q: 'q', x: 'x', r: 'r',
  z: 'z', c: 'c', s: 's', y: 'y', w: 'w', a: 'a', o: 'o', e: 'e',
};

/** 首字 → 声母字母。「沈」念 shěn 不念 chén，所以这一小撮多音字只能硬记 */
const 特例: Record<string, string> = {
  沈: 's', 重: 'c', 单: 's', 仇: 'q', 解: 'x', 查: 'z', 区: 'o', 朴: 'p', 曾: 'z', 盖: 'g',
};

function 声母(字: string): string | null {
  if (特例[字]) return 特例[字];
  const 拼 = 拼音表[字];
  if (!拼) return null;
  for (const 长 of ['zh', 'ch', 'sh']) if (拼.startsWith(长)) return 声母表[长];
  return 声母表[拼[0]] ?? null;
}

/** 昵称 → 字母代号。认不出的字用数字兜底，总之给得出两个字符 */
export function 字母代号(昵称: string, 序号: number): string {
  const 名 = (昵称 ?? '').trim().replace(/^匿名/, '') || (昵称 ?? '').trim();
  // 拉丁字母开头：直接取前两位
  if (/^[a-z]/i.test(名)) return 名.slice(0, 2).toUpperCase();
  const 拼 = 声母(名[0]);
  if (拼) return `${拼}${Math.min(9, 名.length)}`.toUpperCase();
  return String((序号 % 89) + 10);
}
