/**
 * 文字头像。
 *
 * 论坛里有几十个昵称，但没有图片素材——而且也不该有：外部图片要么挂在 CDN 上
 * 随时可能挂，要么内联成 base64 把代码块撑爆。
 *
 * 做法：一个**代号**（不是首字，见下）+ 一个由昵称算出来的稳定颜色。
 * 同一个人永远同一个色；不同的人大概率不同。
 * 手法参考 `酒馆数据/角色卡/寻找伪男` 那张卡的小手机群聊。
 *
 * ── 为什么是代号，不是首字 ──
 * 上一版头像上放昵称首字，结果「蜜源猎人 / 蜜罐猛雌 / 蜜瘾重症 / 蜜语者」四个
 * 全是**蜜**字，一列评论扫下来四个一样的头像。首字在中文昵称上的分辨率极差，
 * 因为大家起名就爱用那几个意象字。
 *
 * 改成按拼音首字母取代号（蜜源猎人 → M4）。这是这里唯一**必须**用等宽字的地方：
 * 头像是一个固定尺寸的方块，字符宽度不一致的话两种头像肉眼看着不一样大。
 */

import { 字母代号 } from './图标';

/**
 * 头像底色板。
 *
 * 全站唯一允许出现的色彩群——理由不是「好看」，是因为**色彩在这里承担信息**：
 * 它标的是「这是谁」。别的所有地方（面板、色块、状态、行动）都走面板自己那四种
 * 漆（紫／桃／金／蓝），一支都不许从这里借。
 *
 * 这一版换了世界（舱壁色块面板），色板跟着重定。约束是三条：
 *
 * 1. **底是纯黑**，头像是一块贴上去的亮色小方块。所以八个色必须**亮到能承受黑字**，
 *    否则黑底上的深色块会糊进背景里，整列头像看起来像有几个是空的。
 *    八个色的 L 全部钉在 0.72——黑字（#14101F，L≈0.20）压上去对比度约 8:1。
 * 2. **色相要散开到看得出是八个人**，但饱和度不能拉满：满饱和的八块贴在纯黑上
 *    会互相抢夺注意力，把正文压下去。C 压在 0.13 附近——是漆，不是荧光贴纸。
 * 3. **必须和面板的四种漆区分开**。面板用紫／桃／金／蓝，所以这里刻意避开
 *    紫（288）与金（85）两个正区间，让头像永远不跟「当前板块」撞。
 */
const 色板 = [
  'oklch(0.72 0.135 25)',   // 砖红
  'oklch(0.72 0.13 48)',    // 陶橙
  'oklch(0.72 0.125 122)',  // 苔绿
  'oklch(0.72 0.125 165)',  // 松青
  'oklch(0.72 0.128 205)',  // 湖蓝
  'oklch(0.72 0.13 250)',   // 钢蓝
  'oklch(0.72 0.135 318)',  // 藕荷
  'oklch(0.72 0.13 350)',   // 陶粉
] as const;

/** 「我」固定用金块——全站最暖的一块，一列里一眼认出自己 */
export const 我的头像 = { 字: '#14100A', 底: '#FFC33A' };

/** 楼主固定用紫块，是全站「面板自己的漆」，跟「我」的金块明确区分 */
export const 楼主头像 = { 字: '#14101F', 底: '#C5B3FF' };

/**
 * 昵称 → 稳定索引。同一个昵称永远同一个值。
 *
 * 用一个简单的字符串散列（djb2 变体）。不需要密码学强度，
 * 只要分布均匀、且在同一份数据里稳定即可。
 */
function 散列(值: string): number {
  let h = 5381;
  for (let i = 0; i < 值.length; i++) {
    h = ((h << 5) + h + 值.charCodeAt(i)) >>> 0;
  }
  return h;
}

/**
 * 取一个昵称的头像配色。
 *
 * @param 我的 是不是「我」——是的话固定 CHALK 块
 * @param 楼主 是不是本帖楼主——是的话固定 RUST 块
 */
export function 头像色(昵称: string, 我的 = false, 楼主 = false): { 字: string; 底: string } {
  if (我的) return 我的头像;
  if (楼主) return 楼主头像;
  return { 字: '#14101F', 底: 色板[散列(昵称 ?? '') % 色板.length] };
}

/**
 * 头像上显示的代号。
 *
 * 用「昵称首字的声母 + 名字长度」，例如「蜜源猎人」→ M4、「尾勾打结」→ W4。
 * 取两个字符而不是一个字，是因为中文昵称的首字分辨率极差：「蜜源猎人 / 蜜罐猛雌 /
 * 蜜瘾重症 / 蜜语者」四个全是**蜜**字，一列评论扫下来四个一样的头像。
 *
 * 拼音表在 `图标.ts` 里，是全站唯一一张（`字母代号`）——这里只做转发，
 * 不再维护第二份表：两份表一定会走散，而头像是最不该出现不一致的地方。
 */
export function 头像字(昵称: string): string {
  return 字母代号(昵称, 散列(昵称 ?? '') % 89);
}
